#ifndef ZOVUTILS_HASH_32_BACKEND_H
#define ZOVUTILS_HASH_32_BACKEND_H
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

typedef struct { uint32_t h[8]; uint64_t bytes; unsigned char b[64]; size_t used; int alg; } zov_h32;
static inline uint32_t zh_rotr(uint32_t x,unsigned n){return(x>>n)|(x<<(32-n));}
static inline uint32_t zh_rotl(uint32_t x,unsigned n){return(x<<n)|(x>>(32-n));}
static inline uint32_t zh_le32(const unsigned char*p){return(uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24;}
static inline uint32_t zh_be32(const unsigned char*p){return(uint32_t)p[0]<<24|(uint32_t)p[1]<<16|(uint32_t)p[2]<<8|p[3];}
static inline void zh_transform(zov_h32*c,const unsigned char*p){
 if(c->alg==0){
  static const uint32_t k[64]={0xd76aa478,0xe8c7b756,0x242070db,0xc1bdceee,0xf57c0faf,0x4787c62a,0xa8304613,0xfd469501,0x698098d8,0x8b44f7af,0xffff5bb1,0x895cd7be,0x6b901122,0xfd987193,0xa679438e,0x49b40821,0xf61e2562,0xc040b340,0x265e5a51,0xe9b6c7aa,0xd62f105d,0x02441453,0xd8a1e681,0xe7d3fbc8,0x21e1cde6,0xc33707d6,0xf4d50d87,0x455a14ed,0xa9e3e905,0xfcefa3f8,0x676f02d9,0x8d2a4c8a,0xfffa3942,0x8771f681,0x6d9d6122,0xfde5380c,0xa4beea44,0x4bdecfa9,0xf6bb4b60,0xbebfbc70,0x289b7ec6,0xeaa127fa,0xd4ef3085,0x04881d05,0xd9d4d039,0xe6db99e5,0x1fa27cf8,0xc4ac5665,0xf4292244,0x432aff97,0xab9423a7,0xfc93a039,0x655b59c3,0x8f0ccc92,0xffeff47d,0x85845dd1,0x6fa87e4f,0xfe2ce6e0,0xa3014314,0x4e0811a1,0xf7537e82,0xbd3af235,0x2ad7d2bb,0xeb86d391};
  static const unsigned char s[64]={7,12,17,22,7,12,17,22,7,12,17,22,7,12,17,22,5,9,14,20,5,9,14,20,5,9,14,20,5,9,14,20,4,11,16,23,4,11,16,23,4,11,16,23,4,11,16,23,6,10,15,21,6,10,15,21,6,10,15,21,6,10,15,21};
  uint32_t m[16];for(int i=0;i<16;i++)m[i]=zh_le32(p+4*i);uint32_t a=c->h[0],b=c->h[1],d=c->h[3],e=c->h[2];
  for(unsigned i=0;i<64;i++){uint32_t f,g;if(i<16){f=(b&e)|(~b&d);g=i;}else if(i<32){f=(d&b)|(~d&e);g=(5*i+1)%16;}else if(i<48){f=b^e^d;g=(3*i+5)%16;}else{f=e^(b|~d);g=(7*i)%16;}uint32_t t=d;d=e;e=b;b+=zh_rotl(a+f+k[i]+m[g],s[i]);a=t;}
  c->h[0]+=a;c->h[1]+=b;c->h[2]+=e;c->h[3]+=d;return;
 }
 if(c->alg==1){uint32_t w[80];for(int i=0;i<16;i++)w[i]=zh_be32(p+4*i);for(int i=16;i<80;i++)w[i]=zh_rotl(w[i-3]^w[i-8]^w[i-14]^w[i-16],1);uint32_t a=c->h[0],b=c->h[1],d=c->h[3],e=c->h[4],f=c->h[2];for(int i=0;i<80;i++){uint32_t q,k;if(i<20){q=(b&f)|(~b&d);k=0x5a827999;}else if(i<40){q=b^f^d;k=0x6ed9eba1;}else if(i<60){q=(b&f)|(b&d)|(f&d);k=0x8f1bbcdc;}else{q=b^f^d;k=0xca62c1d6;}uint32_t t=zh_rotl(a,5)+q+e+k+w[i];e=d;d=f;f=zh_rotl(b,30);b=a;a=t;}c->h[0]+=a;c->h[1]+=b;c->h[2]+=f;c->h[3]+=d;c->h[4]+=e;return;}
 static const uint32_t k[64]={0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2};
 uint32_t w[64];for(int i=0;i<16;i++)w[i]=zh_be32(p+4*i);for(int i=16;i<64;i++){uint32_t x=w[i-15],y=w[i-2],s0=zh_rotr(x,7)^zh_rotr(x,18)^(x>>3),s1=zh_rotr(y,17)^zh_rotr(y,19)^(y>>10);w[i]=w[i-16]+s0+w[i-7]+s1;}uint32_t a=c->h[0],b=c->h[1],d=c->h[3],e=c->h[4],f=c->h[5],g=c->h[6],h=c->h[7],cc=c->h[2];for(int i=0;i<64;i++){uint32_t s1=zh_rotr(e,6)^zh_rotr(e,11)^zh_rotr(e,25),ch=(e&f)^(~e&g),t1=h+s1+ch+k[i]+w[i],s0=zh_rotr(a,2)^zh_rotr(a,13)^zh_rotr(a,22),maj=(a&b)^(a&cc)^(b&cc),t2=s0+maj;h=g;g=f;f=e;e=d+t1;d=cc;cc=b;b=a;a=t1+t2;}c->h[0]+=a;c->h[1]+=b;c->h[2]+=cc;c->h[3]+=d;c->h[4]+=e;c->h[5]+=f;c->h[6]+=g;c->h[7]+=h;
}
static inline void zh_init(zov_h32*c,int alg){memset(c,0,sizeof(*c));c->alg=alg;if(alg==0){c->h[0]=0x67452301;c->h[1]=0xefcdab89;c->h[2]=0x98badcfe;c->h[3]=0x10325476;}else if(alg==1){uint32_t x[]={0x67452301,0xefcdab89,0x98badcfe,0x10325476,0xc3d2e1f0};memcpy(c->h,x,sizeof(x));}else if(alg==2){uint32_t x[]={0xc1059ed8,0x367cd507,0x3070dd17,0xf70e5939,0xffc00b31,0x68581511,0x64f98fa7,0xbefa4fa4};memcpy(c->h,x,sizeof(x));}else{uint32_t x[]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};memcpy(c->h,x,sizeof(x));}}
static inline void zh_update(zov_h32*c,const unsigned char*p,size_t n){c->bytes+=n;while(n){size_t z=64-c->used;if(z>n)z=n;memcpy(c->b+c->used,p,z);c->used+=z;p+=z;n-=z;if(c->used==64){zh_transform(c,c->b);c->used=0;}}}
static inline size_t zh_final(zov_h32*c,unsigned char*out){uint64_t bits=c->bytes*8;c->b[c->used++]=0x80;if(c->used>56){memset(c->b+c->used,0,64-c->used);zh_transform(c,c->b);c->used=0;}memset(c->b+c->used,0,56-c->used);if(c->alg==0){for(int i=0;i<8;i++)c->b[56+i]=(unsigned char)(bits>>(8*i));}else{for(int i=0;i<8;i++)c->b[63-i]=(unsigned char)(bits>>(8*i));}zh_transform(c,c->b);size_t words=c->alg==0?4:c->alg==1?5:c->alg==2?7:8;for(size_t i=0;i<words;i++){if(c->alg==0){for(int j=0;j<4;j++)out[i*4+j]=(unsigned char)(c->h[i]>>(j*8));}else{out[i*4]=(unsigned char)(c->h[i]>>24);out[i*4+1]=(unsigned char)(c->h[i]>>16);out[i*4+2]=(unsigned char)(c->h[i]>>8);out[i*4+3]=(unsigned char)c->h[i];}}return words*4;}
static inline int zov_hash32_run(const char*program,int alg,int argc,char**argv){int status=0,nf=0;char**files=(char**)malloc((size_t)(argc+1)*sizeof(char*));if(!files)return 1;for(int i=0;i<argc;i++){if(!strcmp(argv[i],"--version")){printf("%s (zovutils) 0.9.0\n",program);free(files);return 0;}if(!strcmp(argv[i],"--help")){printf("Usage: %s [OPTION]... [FILE]...\nPrint or check %s checksums.\nWith no FILE, or when FILE is -, read standard input.\n  -b, --binary       read in binary mode\n  -t, --text         read in text mode (default)\n      --help         display this help and exit\n      --version      output version information and exit\n",program,program);free(files);return 0;}if(argv[i][0]=='-'&&strcmp(argv[i],"-")){fprintf(stderr,"%s: unrecognized option '%s'\nTry '%s --help' for more information.\n",program,argv[i],program);free(files);return 1;}files[nf++]=argv[i];}int implicit=!nf;if(implicit)files[nf++]="-";for(int fi=0;fi<nf;fi++){const char*name=files[fi];FILE*f=stdin;if(strcmp(name,"-")){f=fopen(name,"rb");if(!f){fprintf(stderr,"%s: %s: %s\n",program,name,strerror(errno));status=1;continue;}}zov_h32 c;zh_init(&c,alg);unsigned char buf[16384],dig[32];size_t n;while((n=fread(buf,1,sizeof(buf),f)))zh_update(&c,buf,n);if(ferror(f)){fprintf(stderr,"%s: %s: read error: %s\n",program,name,strerror(errno));status=1;}if(f!=stdin)fclose(f);size_t len=zh_final(&c,dig);for(size_t i=0;i<len;i++)printf("%02x",dig[i]);if(implicit)printf("  -\n");else printf("  %s\n",name);}free(files);return status;}
#endif
